test("an evaluator override never inherits the saved provider's key or model", () => {
  const config = toBasteConfig({ evaluator: { provider: "openai", model: "gpt-4o", apiKey: "openai-secret" } }, { evaluatorProvider: "fal" });
  assert.notEqual(config.evaluator.apiKey, "openai-secret");
  assert.equal(config.evaluator.model, "google/gemini-2.5-flash");
  assert.throws(() => toBasteConfig({}, { svgProvider: "made-up" }), /Unsupported SVG provider/);
});

export async function runQD<T>(
  config: QDConfig,
  generateSeed: () => Promise<QDSolution<T>>,
  mutate: (parent: QDSolution<T>, rate: number) => Promise<QDSolution<T>>,
  /** `generation` is 0 for seeds; callers may ignore it. */
  evaluate: (genome: T, context: { generation: number }) => Promise<{ quality: number; features: number[] }>
): Promise<QDArchive<T>> {
  const archive = createArchive<T>(config.features);

  // Initialize with seeds
  const log = config.log ?? console.log;
  log(`🌱 Initializing QD archive with ${config.batchSize} seeds...`);
  for (let i = 0; i < config.batchSize; i++) {
    const seed = await generateSeed();
    const evaluation = await evaluate(seed.genome, { generation: 0 });

    if (evaluation.quality >= config.qualityThreshold) {
      addToArchive(archive, {
        ...seed,
        quality: evaluation.quality,
        features: evaluation.features,
        generation: 0,
      });
    }
  }

  // Evolution loop
  for (let gen = 1; gen <= config.iterations; gen++) {
    log(`\n🧬 Generation ${gen}/${config.iterations}`);
    log(`   Archive: ${archive.cells.size} cells | Coverage: ${(archive.coverage * 100).toFixed(1)}% | Max Q: ${archive.maxQuality.toFixed(3)}`);

    const batchPromises: Promise<void>[] = [];

    for (let b = 0; b < config.batchSize; b++) {
      batchPromises.push(
        (async () => {
          const parent = selectParent(archive);
          if (!parent) return;

          const child = await mutate(parent, config.mutationRate);
          const evaluation = await evaluate(child.genome, { generation: gen });

          if (evaluation.quality >= config.qualityThreshold) {
            addToArchive(archive, {
              ...child,
              quality: evaluation.quality,
              features: evaluation.features,
              generation: gen,
              parents: [getBinKey(parent.features, archive.descriptors)],
            });
          }
        })()
      );
    }

    await Promise.all(batchPromises);
  }

  log(`\n✅ QD Complete!`);
  log(`   Final archive: ${archive.cells.size} cells | Coverage: ${(archive.coverage * 100).toFixed(1)}% | Max Q: ${archive.maxQuality.toFixed(3)}`);

  return archive;
}

/**
 * Get diverse samples from archive for presentation
 */
export function getDiverseSamples<T>(
  archive: QDArchive<T>,
  count: number
): QDSolution<T>[] {
  const solutions = Array.from(archive.cells.values());

  // Sort by quality and then sample across the feature space
  solutions.sort((a, b) => b.quality - a.quality);

  if (solutions.length <= count) return solutions;

  // Greedy selection to maximize feature space coverage
  const selected: QDSolution<T>[] = [];
  const remaining = [...solutions];

  // Always include the best
  selected.push(remaining.shift()!);

  while (selected.length < count && remaining.length > 0) {
